core_reasoning_2:
\section*{Claim}
Let $\widetilde{H}=H+g\delta(x_1+x_2)$ be the auxiliary Hamiltonian obtained by adding the nonlocal contact term to the physical Hamiltonian $H$. If a continuous eigenfunction $\Psi$ of $\widetilde{H}$ is odd under $(x_1,x_2)\mapsto(-x_2,-x_1)$, then $g\delta(x_1+x_2)$ annihilates $\Psi$ distributionally, and $\Psi$ is an eigenfunction of $H$ with the same eigenvalue.

\section*{Premises}
\[
\begin{aligned}
\text{(P1)}&\quad H:=-\frac{\hbar^2}{2m}\frac{\partial^2}{\partial x_1^2}-\frac{\hbar^2}{2m}\frac{\partial^2}{\partial x_2^2}+g\delta(x_1-x_2)+g_B\delta(x_1)+g_B\delta(x_2).\\
\text{(P2)}&\quad \widetilde{H}:=H+g\delta(x_1+x_2).\\
\text{(P3)}&\quad \widetilde{H}\Psi=E\Psi.\\
\text{(P4)}&\quad \Psi(-x_2,-x_1)=-\Psi(x_1,x_2).\\
\text{(P5)}&\quad u:=x_1+x_2,\\quad v:=x_1-x_2,\\quad F(u,v):=\Psi\!\left(\frac{u+v}{2},\frac{u-v}{2}\right).\\
\text{(P6)}&\quad \Psi\text{ is continuous at }x_1+x_2=0.\\
\text{(P7)}&\quad f(u,v)\delta(u)=f(0,v)\delta(u)\quad\text{for every }f\text{ continuous at }u=0.
\end{aligned}
\]

\section*{Derivation}
Under the reflection $(x_1,x_2)\mapsto(-x_2,-x_1)$, the variables in (P5) transform as
\begin{align}
u'&:=(-x_2)+(-x_1)=-(x_1+x_2)=-u,\\
v'&:=(-x_2)-(-x_1)=x_1-x_2=v.
\end{align}
Therefore
\begin{align}
F(-u,v)
&=\Psi\!\left(\frac{-u+v}{2},\frac{-u-v}{2}\right) && \text{by (P5)}\\
&=\Psi\!\left(-\frac{u-v}{2},-\frac{u+v}{2}\right) && \text{algebra}\\
&=-\Psi\!\left(\frac{u+v}{2},\frac{u-v}{2}\right) && \text{by (P4)}\\
&=-F(u,v). && \text{by (P5)}
\end{align}
Setting $u=0$ and using continuity gives
\begin{align}
F(0,v)&=-F(0,v),\\
2F(0,v)&=0,\\
F(0,v)&=0.
\end{align}
The added contact term therefore satisfies
\begin{align}
\delta(x_1+x_2)\Psi(x_1,x_2)
&=\delta(u)F(u,v) && \text{by (P5)}\\
&=F(0,v)\delta(u) && \text{by (P7)}\\
&=0. && \text{by }F(0,v)=0
\end{align}
Hence
\begin{align}
H\Psi
&=(\widetilde{H}-g\delta(x_1+x_2))\Psi && \text{by (P2)}\\
&=\widetilde{H}\Psi-g\delta(x_1+x_2)\Psi && \text{linearity}\\
&=E\Psi-0 && \text{by (P3)}\\
&=E\Psi.
\end{align}

\section*{Final Result}
\[
\boxed{\widetilde{H}\Psi=E\Psi\ \text{and}\ \Psi(-x_2,-x_1)=-\Psi(x_1,x_2)\quad\Longrightarrow\quad H\Psi=E\Psi}
\]
\hfill$\blacksquare$

core_reasoning_3:
\section*{Claim}
Given seed functions $\Psi^{(1)}$ on $A_1$ and $\Psi^{(5)}$ on $A_5$, bosonic exchange symmetry and mirror oddness determine the wavefunction on $A_2,A_3,A_4,A_6$ by the same reconstruction formula as Eq. (8) of the paper.

\section*{Premises}
\[
\begin{aligned}
\text{(P1)}&\quad \Psi(x_2,x_1)=\Psi(x_1,x_2).\\
\text{(P2)}&\quad \Psi(-x_2,-x_1)=-\Psi(x_1,x_2).\\
\text{(P3)}&\quad A_1:=\{(x_1,x_2):0<x_1<x_2\le L/2\}.\\
\text{(P4)}&\quad A_2:=\{(x_1,x_2):0<x_2<x_1\le L/2\}.\\
\text{(P5)}&\quad A_3:=\{(x_1,x_2):-L/2<x_1<x_2<0\}.\\
\text{(P6)}&\quad A_4:=\{(x_1,x_2):-L/2<x_2<x_1<0\}.\\
\text{(P7)}&\quad A_5:=\{(x_1,x_2):-L/2<x_1<0<x_2\le L/2\}.\\
\text{(P8)}&\quad A_6:=\{(x_1,x_2):-L/2<x_2<0<x_1\le L/2\}.\\
\text{(P9)}&\quad \Psi^{(1)}(x_1,x_2):=\Psi(x_1,x_2)\quad\text{for }(x_1,x_2)\in A_1.\\
\text{(P10)}&\quad \Psi^{(5)}(x_1,x_2):=\Psi(x_1,x_2)\quad\text{for }(x_1,x_2)\in A_5.
\end{aligned}
\]

\section*{Derivation}
For $(x_1,x_2)\in A_2$, one has $(x_2,x_1)\in A_1$, so
\begin{align}
\Psi(x_1,x_2)&=\Psi(x_2,x_1) && \text{by (P1)}\\
&=\Psi^{(1)}(x_2,x_1). && \text{by (P9)}
\end{align}
For $(x_1,x_2)\in A_3$, one has $(-x_2,-x_1)\in A_1$, so
\begin{align}
\Psi(x_1,x_2)&=-\Psi(-x_2,-x_1) && \text{by (P2)}\\
&=-\Psi^{(1)}(-x_2,-x_1). && \text{by (P9)}
\end{align}
For $(x_1,x_2)\in A_4$, one has $(x_2,x_1)\in A_3$, so the previous case gives
\begin{align}
\Psi(x_1,x_2)&=\Psi(x_2,x_1) && \text{by (P1)}\\
&=-\Psi^{(1)}(-x_1,-x_2). && \text{apply the }A_3\text{ formula to }(x_2,x_1)
\end{align}
For $(x_1,x_2)\in A_6$, one has $(x_2,x_1)\in A_5$, so
\begin{align}
\Psi(x_1,x_2)&=\Psi(x_2,x_1) && \text{by (P1)}\\
&=\Psi^{(5)}(x_2,x_1). && \text{by (P10)}
\end{align}

\section*{Final Result}
\[
\boxed{\Psi(x_1,x_2)=\begin{cases}
\Psi^{(1)}(x_2,x_1), & (x_1,x_2)\in A_2,\\
-\Psi^{(1)}(-x_2,-x_1), & (x_1,x_2)\in A_3,\\
-\Psi^{(1)}(-x_1,-x_2), & (x_1,x_2)\in A_4,\\
\Psi^{(5)}(x_2,x_1), & (x_1,x_2)\in A_6.
\end{cases}}
\]
\hfill$\blacksquare$

core_reasoning_4:
\section*{Claim}
For $0<k_1<k_2$, the finite reflection orbit used in the Bethe-Ansatz ansatz consists of exactly eight distinct rapidity vectors,
\[
(k_1,k_2),(k_2,k_1),(-k_1,k_2),(-k_2,k_1),(k_1,-k_2),(k_2,-k_1),(-k_1,-k_2),(-k_2,-k_1),
\]
and each corresponding plane wave has kinetic eigenvalue $\hbar^2(k_1^2+k_2^2)/(2m)$ away from the contact hyperplanes.

\section*{Premises}
\[
\begin{aligned}
\text{(P1)}&\quad 0<k_1<k_2.\\
\text{(P2)}&\quad \phi_{\lambda_1,\lambda_2}(x_1,x_2):=e^{i(\lambda_1x_1+\lambda_2x_2)}.\\
\text{(P3)}&\quad S(\lambda_1,\lambda_2):=(\lambda_2,\lambda_1).\\
\text{(P4)}&\quad F_1(\lambda_1,\lambda_2):=(-\lambda_1,\lambda_2),\quad F_2(\lambda_1,\lambda_2):=(\lambda_1,-\lambda_2).\\
\text{(P5)}&\quad \mathcal{O}:=\{S^\sigma F_1^\alpha F_2^\beta(k_1,k_2):\sigma,\alpha,\beta\in\{0,1\}\}.\\
\text{(P6)}&\quad H_0:=-\frac{\hbar^2}{2m}\left(\frac{\partial^2}{\partial x_1^2}+\frac{\partial^2}{\partial x_2^2}\right).\\
\text{(P7)}&\quad \frac{\partial^2}{\partial x_j^2}\phi_{\lambda_1,\lambda_2}=-\lambda_j^2\phi_{\lambda_1,\lambda_2}\quad(j=1,2).
\end{aligned}
\]

\section*{Derivation}
The independent sign flips yield
\begin{align}
F_1^0F_2^0(k_1,k_2)&=(k_1,k_2),\\
F_1^1F_2^0(k_1,k_2)&=(-k_1,k_2),\\
F_1^0F_2^1(k_1,k_2)&=(k_1,-k_2),\\
F_1^1F_2^1(k_1,k_2)&=(-k_1,-k_2).
\end{align}
Swapping those four vectors gives
\begin{align}
S(k_1,k_2)&=(k_2,k_1),\\
S(-k_1,k_2)&=(k_2,-k_1),\\
S(k_1,-k_2)&=(-k_2,k_1),\\
S(-k_1,-k_2)&=(-k_2,-k_1).
\end{align}
Thus
\begin{align}
\mathcal{O}=\{&(k_1,k_2),(k_2,k_1),(-k_1,k_2),(-k_2,k_1),\\
&(k_1,-k_2),(k_2,-k_1),(-k_1,-k_2),(-k_2,-k_1)\}. && \text{by (P5)}
\end{align}
Because $k_1,k_2$ are positive and unequal, no sign-flipped or swapped vector in this list coincides with another one. Hence $|\mathcal{O}|=8$. For any $(\lambda_1,\lambda_2)\in\mathcal{O}$,
\begin{align}
\lambda_1^2+\lambda_2^2&=k_1^2+k_2^2 && \text{sign changes and swaps preserve the sum of squares}.
\end{align}
Therefore
\begin{align}
H_0\phi_{\lambda_1,\lambda_2}
&=-\frac{\hbar^2}{2m}\left(\frac{\partial^2}{\partial x_1^2}+\frac{\partial^2}{\partial x_2^2}\right)\phi_{\lambda_1,\lambda_2} && \text{by (P6)}\\
&=-\frac{\hbar^2}{2m}(-\lambda_1^2-\lambda_2^2)\phi_{\lambda_1,\lambda_2} && \text{by (P7)}\\
&=\frac{\hbar^2}{2m}(\lambda_1^2+\lambda_2^2)\phi_{\lambda_1,\lambda_2} && \text{algebra}\\
&=\frac{\hbar^2}{2m}(k_1^2+k_2^2)\phi_{\lambda_1,\lambda_2}. && \text{orbit-square identity}
\end{align}

\section*{Final Result}
\[
\boxed{(\lambda_1,\lambda_2)\in\mathcal{O}\quad\Longrightarrow\quad H_0\phi_{\lambda_1,\lambda_2}=\frac{\hbar^2}{2m}(k_1^2+k_2^2)\phi_{\lambda_1,\lambda_2}}
\]
\hfill$\blacksquare$

core_reasoning_5:
\section*{Claim}
The paper's Bethe-Ansatz equations define the allowed rapidity set, and the exact point-inversion-odd spectrum obtained by the Asymmetric Bethe Ansatz is the image of that root set under the quadratic map $(k_1,k_2)\mapsto \hbar^2(k_1^2+k_2^2)/(2m)$.

\section*{Premises}
\[
\begin{aligned}
\text{(P1)}&\quad a:=-\frac{\hbar^2}{\mu g},\quad a_B:=-\frac{\hbar^2}{mg_B},\quad \mu:=\frac{m}{2}.\\
\text{(P2)}&\quad 0<k_1<k_2.\\
\text{(P3)}&\quad C_j:=\cos\left(\frac{k_jL}{2}\right),\quad S_j:=\sin\left(\frac{k_jL}{2}\right)\quad(j=1,2).\\
\text{(P4)}&\quad B_1(k_1,k_2):=C_1\left((k_2^2aa_B-2)S_2+k_2(a+2a_B)C_2\right)+k_1aS_1\left(k_2a_BC_2-S_2\right).\\
\text{(P5)}&\quad B_2(k_1,k_2):=k_1^2aS_1S_2+2k_1S_2C_1-k_2^2aS_1S_2-2k_2S_1C_2.\\
\text{(P6)}&\quad \mathcal{R}:=\{(k_1,k_2):0<k_1<k_2,\ B_1(k_1,k_2)=0,\ B_2(k_1,k_2)=0\}.\\
\text{(P7)}&\quad \text{The jump conditions and periodic boundary conditions select precisely the pairs in }\mathcal{R}.\\
\text{(P8)}&\quad \text{Every selected pair has energy }E_{k_1,k_2}:=\frac{\hbar^2}{2m}(k_1^2+k_2^2).
\end{aligned}
\]

\section*{Derivation}
The first Bethe-Ansatz equation is
\begin{align}
B_1(k_1,k_2)&=0 && \text{by (P4) and (P7)}.
\end{align}
The second Bethe-Ansatz equation in the paper is
\begin{align}
k_1^2aS_1S_2+2k_1S_2C_1
&=k_2^2aS_1S_2+2k_2S_1C_2. && \text{boundary compatibility}
\end{align}
Subtracting the right-hand side from both sides gives
\begin{align}
k_1^2aS_1S_2+2k_1S_2C_1-k_2^2aS_1S_2-2k_2S_1C_2&=0,\\
B_2(k_1,k_2)&=0. && \text{by (P5)}
\end{align}
Therefore the set of allowed rapidity pairs is
\begin{align}
\mathcal{R}&=\{(k_1,k_2):0<k_1<k_2,\ B_1(k_1,k_2)=0,\ B_2(k_1,k_2)=0\}. && \text{by (P2), (P6), and (P7)}
\end{align}
For each $(k_1,k_2)\in\mathcal{R}$,
\begin{align}
E_{k_1,k_2}&=\frac{\hbar^2}{2m}(k_1^2+k_2^2) && \text{by (P8)}.
\end{align}
Thus the corresponding energy set is
\begin{align}
\mathcal{E}
&:=\{E_{k_1,k_2}:(k_1,k_2)\in\mathcal{R}\} && \text{definition of the spectral image}\\
&=\left\{\frac{\hbar^2}{2m}(k_1^2+k_2^2):(k_1,k_2)\in\mathcal{R}\right\}. && \text{substitute }E_{k_1,k_2}
\end{align}

\section*{Final Result}
\[
\boxed{\mathcal{E}=\left\{\frac{\hbar^2}{2m}(k_1^2+k_2^2):0<k_1<k_2,\ B_1(k_1,k_2)=0,\ B_2(k_1,k_2)=0\right\}}
\]
\hfill$\blacksquare$

core_reasoning_6:
\section*{Claim}
For repulsive particle-particle and particle-barrier couplings, the $1/g$ expansion reported in the paper has a strictly negative coefficient at order $\xi^{-1}$ and a strictly positive coefficient at order $\xi^{-2}$ for every pair of positive one-body rapidities $\eta_1,\eta_2$.

\section*{Premises}
\[
\begin{aligned}
\text{(P1)}&\quad \xi:=\frac{g}{\hbar^2/(mL)},\quad \xi_B:=\frac{g_B}{\hbar^2/(mL)},\quad \eta_j:=\kappa_jL.\\
\text{(P2)}&\quad \xi>0,\quad \xi_B>0,\quad \eta_1>0,\quad \eta_2>0.\\
\text{(P3)}&\quad E=\frac{\hbar^2}{mL^2}\left\{\epsilon(\eta_1,\eta_2)+\epsilon(\eta_2,\eta_1)+O(\xi^{-3})\right\}.\\
\text{(P4)}&\quad \epsilon(\eta_I,\eta_{II})=\frac{1}{2}\eta_I^2+c_1(\eta_I)\xi^{-1}+c_2(\eta_I,\eta_{II})\xi^{-2}+O(\xi^{-3}).\\
\text{(P5)}&\quad c_1(\eta_I):=-\frac{2\eta_I^2(\eta_I^2+\xi_B^2)}{\eta_I^2+\xi_B(2+\xi_B)}.\\
\text{(P6)}&\quad c_2(\eta_I,\eta_{II}):=\frac{2\eta_I^2(\eta_I^2+\xi_B^2)N(\eta_I,\eta_{II})}{\xi_B(\eta_I^2+\xi_B(2+\xi_B))^3}.\\
\text{(P7)}&\quad N(\eta_I,\eta_{II}):=\eta_I^4(\eta_{II}^2+3\xi_B)+\xi_B^2(2+\xi_B)\left(3\xi_B^2+\eta_{II}^2(2+\xi_B)\right)\\
&\qquad\qquad{}+2\eta_I^2\xi_B\left(\eta_{II}^2(2+\xi_B)+\xi_B(5+3\xi_B)\right).\\
\text{(P8)}&\quad C_1:=c_1(\eta_1)+c_1(\eta_2),\quad C_2:=c_2(\eta_1,\eta_2)+c_2(\eta_2,\eta_1).
\end{aligned}
\]

\section*{Derivation}
For $c_1$, positivity of the factors gives
\begin{align}
2\eta_I^2&>0,\\
\eta_I^2+\xi_B^2&>0,\\
\eta_I^2+\xi_B(2+\xi_B)&>0,
\end{align}
so
\begin{align}
\frac{2\eta_I^2(\eta_I^2+\xi_B^2)}{\eta_I^2+\xi_B(2+\xi_B)}&>0,\\
c_1(\eta_I)&<0 && \text{by (P5)}.
\end{align}
Therefore
\begin{align}
C_1=c_1(\eta_1)+c_1(\eta_2)&<0. && \text{by (P8)}
\end{align}
For $c_2$, each summand in $N$ is positive:
\begin{align}
\eta_I^4(\eta_{II}^2+3\xi_B)&>0,\\
\xi_B^2(2+\xi_B)\left(3\xi_B^2+\eta_{II}^2(2+\xi_B)\right)&>0,\\
2\eta_I^2\xi_B\left(\eta_{II}^2(2+\xi_B)+\xi_B(5+3\xi_B)\right)&>0.
\end{align}
Thus
\begin{align}
N(\eta_I,\eta_{II})&>0,\\
2\eta_I^2(\eta_I^2+\xi_B^2)N(\eta_I,\eta_{II})&>0,\\
\xi_B(\eta_I^2+\xi_B(2+\xi_B))^3&>0,\\
c_2(\eta_I,\eta_{II})&>0 && \text{by (P6)}.
\end{align}
Therefore
\begin{align}
C_2=c_2(\eta_1,\eta_2)+c_2(\eta_2,\eta_1)&>0. && \text{by (P8)}
\end{align}

\section*{Final Result}
\[
\boxed{\xi>0,\ \xi_B>0,\ \eta_1,\eta_2>0\quad\Longrightarrow\quad C_1<0\ \text{and}\ C_2>0}
\]
\hfill$\blacksquare$

core_reasoning_7:
\section*{Claim}
If $a_B=-a/2$, equivalently $g_B=-g$, then every integer pair $n_1,n_2\in\mathbb{Z}$ with $0<n_1<n_2$ gives rapidities $k_j=2\pi n_j/L$ satisfying both Bethe-Ansatz equations, and the corresponding energy equals the barrier-free noninteracting two-particle ring energy.

\section*{Premises}
\[
\begin{aligned}
\text{(P1)}&\quad a:=-\frac{\hbar^2}{\mu g},\quad a_B:=-\frac{\hbar^2}{mg_B},\quad \mu:=\frac{m}{2},\quad g\ne0,
\quad L>0.\\
\text{(P2)}&\quad B_1(k_1,k_2):=\cos\left(\frac{k_1L}{2}\right)\left((k_2^2aa_B-2)\sin\left(\frac{k_2L}{2}\right)+k_2(a+2a_B)\cos\left(\frac{k_2L}{2}\right)\right)\\
&\qquad\qquad{}+k_1a\sin\left(\frac{k_1L}{2}\right)\left(k_2a_B\cos\left(\frac{k_2L}{2}\right)-\sin\left(\frac{k_2L}{2}\right)\right).\\
\text{(P3)}&\quad B_2(k_1,k_2):=k_1^2a\sin\left(\frac{k_1L}{2}\right)\sin\left(\frac{k_2L}{2}\right)+2k_1\sin\left(\frac{k_2L}{2}\right)\cos\left(\frac{k_1L}{2}\right)\\
&\qquad\qquad{}-k_2^2a\sin\left(\frac{k_1L}{2}\right)\sin\left(\frac{k_2L}{2}\right)-2k_2\sin\left(\frac{k_1L}{2}\right)\cos\left(\frac{k_2L}{2}\right).\\
\text{(P4)}&\quad \text{The Bethe-Ansatz equations are }B_1(k_1,k_2)=0\text{ and }B_2(k_1,k_2)=0.\\
\text{(P5)}&\quad E_{k_1,k_2}:=\frac{\hbar^2}{2m}(k_1^2+k_2^2).\\
\text{(P6)}&\quad n_1,n_2\in\mathbb{Z},\quad 0<n_1<n_2,\quad k_j:=\frac{2\pi n_j}{L}\quad(j=1,2).\\
\text{(P7)}&\quad \sin(\pi n)=0\text{ and }\cos(\pi n)=(-1)^n\text{ for every }n\in\mathbb{Z}.\\
\text{(P8)}&\quad E^{(0)}_{n_1,n_2}:=\frac{2\pi^2\hbar^2}{mL^2}(n_1^2+n_2^2).
\end{aligned}
\]

\section*{Derivation}
From (P1),
\begin{align}
a&=-\frac{\hbar^2}{(m/2)g}=-\frac{2\hbar^2}{mg},\\
-\frac{a}{2}&=\frac{\hbar^2}{mg}.
\end{align}
Therefore
\begin{align}
a_B=-\frac{a}{2}
&\Longleftrightarrow -\frac{\hbar^2}{mg_B}=\frac{\hbar^2}{mg} && \text{by (P1)}\\
&\Longleftrightarrow -\frac{1}{g_B}=\frac{1}{g} && \text{multiply by }m/\hbar^2\\
&\Longleftrightarrow g_B=-g. && \text{invert nonzero couplings}
\end{align}
Assume $a_B=-a/2$. Then
\begin{align}
a+2a_B&=a+2\left(-\frac{a}{2}\right)=0.
\end{align}
For the integer rapidities,
\begin{align}
\sin\left(\frac{k_jL}{2}\right)&=\sin\left(\frac{(2\pi n_j/L)L}{2}\right)=\sin(\pi n_j)=0,\\
\cos\left(\frac{k_jL}{2}\right)&=\cos(\pi n_j)=(-1)^{n_j}.
\end{align}
Substituting into $B_1$ gives
\begin{align}
B_1(k_1,k_2)
&=(-1)^{n_1}\left((k_2^2aa_B-2)\cdot0+k_2(a+2a_B)(-1)^{n_2}\right)\\
&\qquad{}+k_1a\cdot0\left(k_2a_B(-1)^{n_2}-0\right) && \text{by (P2)}\\
&=(-1)^{n_1+n_2}k_2(a+2a_B)\\
&=0.
\end{align}
Substituting into $B_2$ gives
\begin{align}
B_2(k_1,k_2)
&=k_1^2a\cdot0\cdot0+2k_1\cdot0\cdot(-1)^{n_1}-k_2^2a\cdot0\cdot0-2k_2\cdot0\cdot(-1)^{n_2} && \text{by (P3)}\\
&=0.
\end{align}
Thus both Bethe-Ansatz equations hold. The energy is
\begin{align}
E_{k_1,k_2}
&=\frac{\hbar^2}{2m}\left[\left(\frac{2\pi n_1}{L}\right)^2+\left(\frac{2\pi n_2}{L}\right)^2\right] && \text{by (P5) and (P6)}\\
&=\frac{2\pi^2\hbar^2}{mL^2}(n_1^2+n_2^2)\\
&=E^{(0)}_{n_1,n_2}. && \text{by (P8)}
\end{align}

\section*{Final Result}
\[
\boxed{a_B=-a/2\ \Longleftrightarrow\ g_B=-g,\quad k_j=2\pi n_j/L\ (0<n_1<n_2)\ \Longrightarrow\ B_1=B_2=0\ \text{and}\ E_{k_1,k_2}=E^{(0)}_{n_1,n_2}}
\]
\hfill$\blacksquare$
